const SCHOLAR = 'https://scholar.google.com/citations?user=V6ELkxMAAAAJ&hl=en';
const GITHUB = 'https://github.com/phytnesskun/personal_web';
const EMAIL = 'bingkunqi@gmail.com';
let content;
const routeParts = location.pathname.split('/').filter(Boolean);
const urlLanguage = ['zh','en'].includes(routeParts[0]) ? routeParts.shift() : null;
let lang = urlLanguage || 'zh';
const path = '/' + routeParts.join('/');
const route = path.startsWith('/projects/') ? 'project' : path === '/research' ? 'research' : path === '/about' ? 'about' : path === '/teaching' ? 'teaching' : 'home';
const projectId = routeParts[1];
const languageUrl = l => '/' + l + (path === '/' ? '/' : path + '/') + location.hash;
Object.assign(UI.zh, {intro:'我是亓炳堃，国际学校物理与数学教师、非厄米光子学研究者，也是一名 AI 教学工具开发者。我把研究中的好奇心带进课堂，再把教学中的需求做成工具。',contactIntro:'欢迎交流国际课程教学、教育工具合作与物理研究。邮件中可以告诉我你的问题或想法。'});
Object.assign(UI.en, {intro:'I’m Bingkun Qi: an international-school physics and mathematics teacher, a researcher in non-Hermitian photonics, and a builder of teaching tools with AI. I bring research questions into the classroom and turn teaching needs into tools.',contactIntro:'For international science teaching, educational tool collaborations or physics research, send me a question or an idea.'});
const esc = s => String(s ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const arrow = '<span aria-hidden="true">↗</span>';
const external = (url, text, cls='text-link') => `<a class="${cls}" href="${esc(url)}" target="_blank" rel="noopener noreferrer">${esc(text)} ${arrow}</a>`;

function header(t) {
 return `<a class="skip" href="#main">${t.skip}</a><header class="site-header wrap"><a href="/" class="brand" aria-label="${esc(t.footer)}"><span class="brand-mark" aria-hidden="true">亓</span><span>${t.name}<small>${lang==='zh'?'BINGKUN QI':'PHYSICS, TEACHING & AI'}</small></span></a><button class="menu-toggle" aria-label="${t.menu}" aria-expanded="false" aria-controls="navigation"><span></span><span></span></button><nav id="navigation" aria-label="${lang==='zh'?'主导航':'Main navigation'}"><a href="/#projects">${t.nav[0]}</a><a href="/teaching/" ${route==='teaching'?'aria-current="page"':''}>${lang==='zh'?'教学':'Teaching'}</a><a href="/research/" ${route==='research'?'aria-current="page"':''}>${t.nav[1]}</a><a href="/about/" ${route==='about'?'aria-current="page"':''}>${t.nav[2]}</a><a href="#contact">${t.nav[3]}</a><div class="language" aria-label="Language"><button data-lang="zh" aria-pressed="${lang==='zh'}">中</button><span>/</span><button data-lang="en" aria-pressed="${lang==='en'}">EN</button></div></nav></header>`;
}
function footer(t) {
 return `<section class="contact wrap" id="contact"><div><p class="eyebrow">${t.contactLabel}</p><h2>${t.contactTitle}</h2><p>${t.contactIntro}</p></div><div class="contact-links"><a class="button dark" href="mailto:${EMAIL}">${t.email} ${arrow}</a>${external(SCHOLAR,t.scholar)}${external(GITHUB,'GitHub')}</div></section><footer class="site-footer wrap"><span>© ${new Date().getFullYear()} ${t.footer}</span><span>${t.footerNote}</span><a href="#top" aria-label="${lang==='zh'?'回到顶部':'Back to top'}">↑</a></footer>`;
}
function paperRow(p,t,index) {
 return `<article class="paper-row"><span class="paper-number">${String(index+1).padStart(2,'0')}</span><div><p class="paper-meta">${esc(p.journal)} <span>${p.year}</span></p><h3><a href="${esc(p.url)}" target="_blank" rel="noopener noreferrer">${esc(p.title)} ${arrow}</a></h3>${route==='research'?`<p class="authors">${esc(p.authors)}</p><p class="paper-summary">${esc(p.summary)}</p>`:''}</div></article>`;
}
function projectRows(d,t,current='') {
 return d.projects.filter(p=>p.id!==current).map((p,i)=>`<a class="project-row" href="/projects/${esc(p.id)}/"><span class="project-order">${String(i+1).padStart(2,'0')}</span><div><p class="small-label">${esc(p.kicker)}</p><h3>${esc(p.title)}</h3><p>${esc(p.summary)}</p></div><span class="circle-arrow" aria-hidden="true">↗</span></a>`).join('');
}
function projectArt(t,kind='caie-physics') {
 const labels={'caie-physics':['9702','PHYSICS','AS'],'igcse-maths':['4MB1','MATHEMATICS','IGCSE'],'edexcel-maths':['A–L','MATHEMATICS','EDEXCEL'],esat:['ESAT','SCIENCE & MATHEMATICS','PRACTICE'],'student-feedback':['FEED','STUDENT FEEDBACK','TEACHING']};
 const l=labels[kind]||labels['caie-physics'];
 return `<div class="project-art" aria-label="${esc(l.join(' '))}"><div class="art-top"><span>${l[1]}</span><span>${l[2]}</span></div><span class="art-code">${l[0]}</span><svg class="art-wave" viewBox="0 0 480 130" aria-hidden="true"><path d="M0 65 Q30 0 60 65 T120 65 T180 65 T240 65 T300 65 T360 65 T420 65 T480 65"/><path d="M0 65 Q30 130 60 65 T120 65 T180 65 T240 65 T300 65 T360 65 T420 65 T480 65"/><line x1="0" y1="65" x2="480" y2="65"/></svg><div class="art-bottom">${kind==='caie-physics'?`<strong>3,232 <span>${t.questionCount}</span></strong><span>${t.countDate}</span>`:`<strong>${l[1]}</strong><span>${lang==='zh'?'教学工具系列':'TEACHING TOOLS'}</span>`}</div></div>`;
}
function home(d,t) {
 return `<main id="main"><section class="hero wrap"><div class="hero-copy"><p class="eyebrow"><span class="small-star" aria-hidden="true">✳</span> ${t.eyebrow}</p><h1>${t.hero}</h1><p class="hero-intro">${t.intro}</p><div class="hero-actions"><a href="#projects" class="button dark">${t.projects} ${arrow}</a><a href="/research/" class="text-link">${t.research} <span aria-hidden="true">→</span></a></div></div><figure class="hero-portrait"><div class="portrait-frame"><img src="/assets/portrait.png" width="1440" height="1439" alt="${t.portrait}" fetchpriority="high"><span class="portrait-index">BQ / 01</span></div><figcaption>${t.caption}</figcaption><span class="portrait-star" aria-hidden="true">✳</span></figure></section><div class="credentials wrap">${t.credentials.map(x=>`<span><i aria-hidden="true"></i>${x}</span>`).join('')}</div>
 <section class="section wrap" id="projects"><div class="section-heading"><div><p class="eyebrow">${t.selected}</p><h2>${t.workTitle}</h2></div><p class="section-lead">${t.workIntro}</p></div><article class="featured"><div class="feature-copy"><p class="small-label">${t.featureLabel}</p><h3>${t.featureTitle}</h3><p>${t.featureDesc}</p><a class="button light" href="/projects/caie-physics/">${t.case} ${arrow}</a></div><a href="/projects/caie-physics/" class="feature-cover" aria-label="${t.case}"><div class="product-cover"><img src="/assets/caie-interface.png" width="1265" height="712" alt="${lang==='zh'?'AS 物理题库的筛选与选题篮界面':'AS Physics question filters and selection basket'}" loading="lazy"><span>${lang==='zh'?'真实界面 · AS 阶段':'LIVE INTERFACE · AS STAGE'}</span></div></a></article><div class="project-list">${projectRows(d,t,'caie-physics')}</div></section>
 <section class="lab-section"><div class="wrap lab-layout"><div class="lab-copy"><p class="eyebrow">${t.labLabel}</p><h2>${t.labTitle}</h2><p>${t.labIntro}</p><div class="lab-note"><span aria-hidden="true">∿</span><small>${lang==='zh'?'一个关于波的叠加的小实验':'A small experiment in wave superposition'}</small></div></div><wave-lab lang="${lang}"></wave-lab></div><div class="wrap lesson-cta"><a class="text-link" href="/teaching/">${lang==='zh'?'跟着 10 分钟教学示例继续探索':'Follow the 10-minute guided lesson'} ${arrow}</a><span>${lang==='zh'?'预测 · 观察 · 推导 · 双语讲义':'Predict · Observe · Derive · Printable handout'}</span></div></section>
 <section class="section wrap" id="research"><div class="section-heading"><div><p class="eyebrow">${t.researchLabel}</p><h2>${t.researchTitle}</h2></div><div class="section-lead"><p>${t.researchIntro}</p><a href="/research/" class="text-link">${t.allResearch} ${arrow}</a></div></div><div class="paper-list">${[d.papers[3],d.papers[0],d.papers[2]].map((p,i)=>paperRow(p,t,i)).join('')}</div></section>
 <section class="about-strip wrap"><div><p class="eyebrow">${t.aboutLabel}</p><h2>${t.aboutTitle}</h2><p>${t.aboutIntro}</p><a href="/about/" class="text-link">${t.moreAbout} ${arrow}</a></div><div class="life-type"><span class="life-line" aria-hidden="true">↗</span>${t.life.map((x,i)=>`<span class="life-word life-word-${i}">${x}</span>`).join('')}<p>${t.lifeNote}</p></div></section></main>`;
}
function research(d,t) {
 return `<main id="main" class="wrap inner-main"><a class="back-link" href="/">← ${t.back}</a><section class="page-heading"><p class="eyebrow">RESEARCH / SELECTED PUBLICATIONS</p><h1>${t.researchPageTitle}</h1><p>${t.researchPageIntro}</p><div class="area-list">${t.researchAreas.map(x=>`<span>${x}</span>`).join('')}</div>${external(SCHOLAR,t.scholar)}</section>${researchExplainers(d)}<h2 class="publication-heading">${lang==='zh'?'论文目录':'Publications'}</h2><div class="paper-list full-papers">${d.papers.map((p,i)=>paperRow(p,t,i)).join('')}</div></main>`;
}
function about(d,t) {
 return `<main id="main" class="wrap inner-main"><a class="back-link" href="/">← ${t.back}</a><section class="about-hero"><div class="page-heading"><p class="eyebrow">ABOUT / BINGKUN QI</p><h1>${t.aboutPageTitle}</h1><p>${esc(d.about.intro)}</p>${d.about.paragraphs.map(x=>`<p>${esc(x)}</p>`).join('')}</div><figure><img src="/assets/portrait.png" width="1440" height="1439" alt="${t.portrait}"><figcaption>${t.caption}</figcaption></figure></section><section class="bio-section"><h2>${t.education}</h2><div class="timeline">${d.education.map(x=>`<article><span class="timeline-period">${esc(x.period)}</span><div><h3>${esc(x.institution)}</h3><p>${esc(x.detail)}</p></div></article>`).join('')}</div></section><section class="bio-section"><h2>${t.teaching}</h2><div><p class="bio-lead">${t.teachingIntro}</p>${d.about.teaching.map((x,i)=>`<p class="numbered-copy"><span>0${i+1}</span>${esc(x)}</p>`).join('')}</div></section><section class="bio-section"><h2>${t.lifeTitle}</h2><div>${d.about.life.map(x=>`<p>${esc(x)}</p>`).join('')}</div></section></main>`;
}
function project(d,t) {
 const p=d.projects.find(x=>x.id===projectId);
 if(!p) return `<main id="main" class="wrap inner-main"><h1>404</h1><a href="/">${t.back}</a></main>`;
 return `<main id="main" class="wrap inner-main"><a class="back-link" href="/#projects">← ${t.backProjects}</a><section class="project-heading page-heading"><p class="eyebrow">${esc(p.kicker)}</p><h1>${esc(p.title)}</h1><p>${esc(p.summary)}</p>${external(p.url,p.id==='student-feedback'?(lang==='zh'?'访问系统':'Open system'):t.visit,'button dark')}</section>${['caie-physics','student-feedback'].includes(p.id)?caseStudy(p):`<div class="project-banner">${projectArt(t,p.id)}</div>`}<div class="project-body"><div><section><h2>${t.overview}</h2>${p.story.map(x=>`<p>${esc(x)}</p>`).join('')}</section><section><h2>${t.features}</h2><ul class="feature-list">${p.features.map(x=>`<li>${esc(x)}</li>`).join('')}</ul></section>${p.id==='caie-physics'?`<section><h2>${t.workflow}</h2><p>${t.workflowIntro}</p><ol class="workflow-list">${t.steps.map((x,i)=>`<li><span>0${i+1}</span>${x}</li>`).join('')}</ol></section>`:''}</div><aside><p class="eyebrow">${t.access}</p><p>${p.id==='student-feedback'?(lang==='zh'?'系统提供教师与学生各自的使用入口，支持中文与英文界面。':'The system provides separate entry points for teachers and students, with Chinese and English interfaces.'):t.accessNote}</p>${external(p.url,p.id==='student-feedback'?(lang==='zh'?'访问系统':'Open system'):t.visit)}<hr>${external(SCHOLAR,t.scholar)}</aside></div><section class="related-projects"><h2>${t.moreProjects}</h2>${projectRows(d,t,p.id)}</section></main>`;
}
function render() {
 const t=UI[lang], d=content[lang];
 const previousLab=document.querySelector('wave-lab');
 const menuWasOpen=document.querySelector('.menu-toggle')?.getAttribute('aria-expanded')==='true';
 document.documentElement.lang=lang==='zh'?'zh-CN':'en';
 document.body.dataset.language=lang;
 document.title = `${route==='research'?t.researchPageTitle:route==='about'?t.aboutPageTitle:route==='teaching'?d.teachingExample.title:route==='project'?(d.projects.find(p=>p.id===projectId)?.title||'Project'):t.footer} — ${lang==='zh'?'物理 · 教学 · AI':'Physics · Teaching · AI'}`;
 document.getElementById('app').innerHTML=header(t)+({home,research,about,project,teaching}[route](d,t))+footer(t);
 if(previousLab&&document.querySelector('wave-lab')){document.querySelector('wave-lab').replaceWith(previousLab);previousLab.setAttribute('lang',lang);}
 document.querySelectorAll('[data-lang]').forEach(b=>b.addEventListener('click',()=>{if(lang===b.dataset.lang)return;const y=scrollY;lang=b.dataset.lang;history.pushState({language:lang},'',languageUrl(lang));try{localStorage.setItem('bq-language',lang);}catch{}render();scrollTo(0,y);document.querySelector(`[data-lang="${lang}"]`)?.focus({preventScroll:true});}));
 enhancePage();
 const menu=document.querySelector('.menu-toggle'), nav=document.getElementById('navigation');
 if(menuWasOpen){menu.setAttribute('aria-expanded','true');nav.classList.add('open');}
 menu.addEventListener('click',()=>{const open=menu.getAttribute('aria-expanded')!=='true';menu.setAttribute('aria-expanded',String(open));nav.classList.toggle('open',open);});
 nav.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>{nav.classList.remove('open');menu.setAttribute('aria-expanded','false');}));
}
document.addEventListener('keydown',e=>{const menu=document.querySelector('.menu-toggle');if(e.key==='Escape'&&menu?.getAttribute('aria-expanded')==='true'){document.getElementById('navigation')?.classList.remove('open');menu.setAttribute('aria-expanded','false');menu.focus();}});
fetch('/assets/content.json').then(r=>{if(!r.ok)throw new Error('Content unavailable');return r.json();}).then(d=>{content=d;render();if(location.hash)requestAnimationFrame(()=>document.querySelector(location.hash)?.scrollIntoView());}).catch(()=>{document.getElementById('app').innerHTML=`<main class="wrap inner-main"><h1>Bingkun Qi</h1><p>${UI[lang].error}</p><a href="${SCHOLAR}">Google Scholar ↗</a></main>`;});

window.addEventListener('popstate',()=>{lang=location.pathname.split('/')[1]==='en'?'en':'zh';render();});
